const isValidSmtpSecure = /^(true|false)$/.test(process.env.SMTP_SECURE || 'false');

const isValidSmtpHost = /^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/.test(
  process.env.SMTP_HOST || ''
);
```

