// Simple application with environment variable configuration
const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
require('dotenv').config();

const app = express();

// Load configuration from environment variables with defaults
const config = {
  port: parseInt(process.env.PORT || '3000', 10),
  corsOrigin: process.env.CORS_ORIGIN || '*',
  corsMethods: (process.env.CORS_METHODS || 'GET,POST').split(',').map(m => m.trim()),
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
  headers: {
    'X-Content-Type-Options': process.env.X_CONTENT_TYPE_OPTIONS || 'nosniff',
    'X-Frame-Options': process.env.X_FRAME_OPTIONS || 'DENY',
  }
};

// Security middleware
app.use(cors({
  origin: config.corsOrigin !== '*' ? config.corsOrigin : true, // true = allow origin from request
  methods: config.corsMethods
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMax,
  message: 'Too many requests from this IP'
});
app.use('/api/', limiter);

// Custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', config.headers['X-Content-Type-Options']);
  res.setHeader('X-Frame-Options', config.headers['X-Frame-Options']);
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
